perspectives.style:
@settings {
  font-scale: 1.2;
  layout-gravity: 0.0001;
  layout-particle-charge: 300;
}

/* Style des dossiers */
[type="folder"] {
  color: #f4a261;
  size: 30;
  shape: square;
  font-size: 14;
}

/* Style des fichiers TypeScript */
[extension=".tsx"] {
  color: #3178c6;
  size: scale("lines", 10, 100);
  shape: circle;
}

[extension=".ts"] {
  color: #007acc;
  size: scale("lines", 10, 100);
  shape: circle;
}

/* Style des fichiers JavaScript */
[extension=".jsx"] {
  color: #f7df1e;
  size: scale("lines", 10, 100);
  shape: circle;
}

[extension=".js"] {
  color: #f0db4f;
  size: scale("lines", 10, 100);
  shape: circle;
}

/* Connexions d'imports (entre fichiers) */
[connection type="import"] {
  color: #2a9d8f;
  width: 2;
  arrow-size: 0.5;
}

/* Hiérarchie entre dossiers */
[connection type="folder-hierarchy"] {
  color: #e76f51;
  width: 1.5;
  style: dashed;
  arrow-visibility: hidden;
}

/* Appartenance fichier -> dossier */
[connection type="file-in-folder"] {
  color: #8338ec;
  width: 1;
  style: dotted;
  arrow-visibility: hidden;
}

/* Fichiers avec beaucoup de lignes */
[lines > 300] {
  border-width: 3;
  border-color: #e63946;
}

/* Fichiers moyens */
[lines > 100][lines < 300] {
  border-width: 2;
  border-color: #f77f00;
}

/* Petits fichiers */
[lines < 100] {
  border-width: 1;
  border-color: #06d6a0;
}
